\begin{aligned}
\p(S) &= \p(E \or E^\c) && \text{$E$ or $E^\c$ covers every outcome in the sample space} \\
\p(S) &= \p(E) + \p(E^\c) && \text{Events $E$ and $E^\c$ are mututally exclusive} \\
1 &= \p(E) + \p(E^\c) && \text{Axiom 2 of probability} \\
\p(E^\c) &= 1 - \p(E) && \text{By re-arranging}
\end{aligned}
